        return (
            f"{self.name} ({self.packaging})\n"
            f"  {self.candy_weight:.2f} lbs. @ ${self.price_per_pound:.2f}/lb: ${self.calculate_cost():.2f} [Tax: ${self.calculate_tax():.2f}]"
