            rows.append([
                lines[0],
                f"${item.calculate_cost():.2f}",
                f"[Tax: ${item.calculate_tax():.2f}]"
            ])
            for detail in lines[1:]:
                rows.append([detail, "", ""])

        rows.append(["----------", "----------", "----------"])
        rows.append([
            "Total number of items in order:",
