            ""
        ])
        rows.append([
            "Order Subtotals:",
            f"${self.order_cost():.2f}",
            f"[Tax: ${self.order_tax():.2f}]"
        ])
        rows.append([
            "Order Total:",
            "",
            f"${self.order_cost() + self.order_tax():.2f}"
        ])
        return rows

