def main() -> None:
    shop = DessertShop()
    order = Order()

    done = False
    prompt = (
        "\n1: Candy"
        "\n2: Cookie"
        "\n3: Ice Cream"
        "\n4: Sundae"
        "\n\nWhat would you like to add to the order? (1-4, Enter for done): "
    )

    while not done:
        choice = input(prompt)
        match choice.strip():
            case "":
                done = True
            case "1":
                item = shop.user_prompt_candy()
                order.add(item)
                print(f"{item.name} has been added to your order.")
            case "2":
                item = shop.user_prompt_cookie()
                order.add(item)
                print(f"{item.name} has been added to your order.")
            case "3":
                item = shop.user_prompt_icecream()
                order.add(item)
                print(f"{item.name} has been added to your order.")
            case "4":
                item = shop.user_prompt_sundae()
                order.add(item)
                print(f"{item.name} has been added to your order.")
            case _:
                print("Invalid response: Please enter a choice from the menu (1-4) or Enter")

    print()

    data = []
    for item in order:
        data.append([
            item.name,
            f"${item.calculate_cost():.2f}",
            f"${item.calculate_tax():.2f}"
        ])

    subtotal = order.order_cost()
    total_tax = order.order_tax()
    total = round(subtotal + total_tax, 2)

    data.append([
        "Order Subtotals",
        f"${subtotal:.2f}",
        f"${total_tax:.2f}"
    ])
    data.append([
        "Order Total",
        "",
        f"${total:.2f}"
    ])
    data.append([
        "Total Items in the order:",
        "",
        len(order)
    ])

    print(tabulate(data, headers=["Name", "Cost", "Tax"], tablefmt="simple"))


if __name__ == "__main__":
    main()
